import RequestError from "#helpers/requestError";
import Service from "#class/service";
import type { Pakketdata, PakketId, Polisdata, PolisId, PolisOfPakketResultaat, SubPolisRij, Validator } from "#types";

export default class PolisService extends Service {

    getPolisData(polisId: PolisId): Promise<Polisdata>;
    getPolisData(pakketId: PakketId): Promise<Pakketdata>;
    getPolisData(id: PolisId | PakketId): Promise<Polisdata | Pakketdata>;
    async getPolisData(id: PolisId | PakketId): Promise<Polisdata | Pakketdata> {
        try {
            return await this.session.getAxon<Polisdata | Pakketdata>(`policies/${id}`);
        } catch (err) {
            throw (err instanceof RequestError && err.res?.status === 403)
                ? new Error(`Status 403, is het polis-/pakketnummer wel geldig?`)
                : err;
        }
    }

    /**
     * @returns polisdata als een polis/pakket bestaat voor de opgegeven identifier, `false` als een polis/pakket *misschien* niet bestaat.
     * */
    async policyAccessible(polisId: PolisId) {
        try {
            return await this.session.getAxon(`policies/${polisId}`);
        } catch (err) {
            if (err instanceof RequestError && err.status === 403) return false;
            throw err;
        }
    }

    /**
     * Normaliseert een polisnummer dat óf een losse polis óf een pakket kan zijn
     * naar één vorm: een lijst polisnummers plus een lazy loader voor hun data.
     *
     * - Losse polis → `type: "polis"`. Gedraagt zich als een pakket van één:
     *   `polisnummers` bevat alleen de polis zelf, `subpolissen` is `null`.
     * - Pakket → `type: "pakket"`. De subpolissen worden gefilterd door
     *   `validator` en uitgeklapt naar hun polisnummers.
     *
     * `data()` levert de volledige {@link Polisdata} per polisnummer, pas bij
     * aanroep. Bij een losse polis is dat gratis (de data is al binnen); bij een
     * pakket kost het één request per subpolis, sequentieel.
     *
     * NB: `validator` filtert alléén subpolissen. Een losse polis wordt altijd
     * teruggegeven, ook als de validator die zou hebben afgewezen.
     *
     * @param polisnummer Polis of pakket om op te vragen. Default: de actieve polis.
     * @param validator Filter voor subpolissen van een pakket. Default: alles toelaten.
     */
    async polisOfPakket(polisnummer: PolisId | PakketId, validator: Validator<SubPolisRij> = () => true): Promise<PolisOfPakketResultaat | null> {
        let data: Polisdata | Pakketdata;
        try { data = await this.getPolisData(polisnummer) }
        catch (err) {
            if (err instanceof RequestError && err.status === 403) throw new Error("De polis bestaat niet");
            else throw err;
        }

        if (!data.isPackage) return {
            type: "polis",
            polisnummers: [data.externalIdentifier],
            subpolissen: null,
            data: () => Promise.resolve([data]),
        };

        const subpolissen = data.subPolicyList.filter(validator);
        console.debug(subpolissen.map(s => s.productName).join(", "))
        return {
            type: "pakket",
            polisnummers: subpolissen.map(p => p.policyIdentifier),
            subpolissen,
            data: async () => {
                const polissen: Polisdata[] = [];
                for (const { policyIdentifier } of subpolissen)
                    polissen.push(await this.getPolisData(policyIdentifier));
                return polissen;
            },
        };
    }
}